parameters.text:
=Empresa: {{ $json.empresa }}
Negocio / rubro: {{ $json.negocio || 'No informado' }}
Problema declarado: {{ $json.problema }}
Presupuesto estimado (USD): {{ $json.presupuesto_usd }}
Clasificación asignada por el Manager: {{ $json.clasificacion }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "servicios_recomendados": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "Automatización con n8n",
          "Agentes IA",
          "Chatbots",
          "Automatización Documental",
          "Dashboards Power BI"
        ]
      }
    },
    "alcance_propuesto": {
      "type": "string"
    },
    "complejidad": {
      "type": "string",
      "enum": [
        "BAJA",
        "MEDIA",
        "ALTA"
      ]
    },
    "justificacion": {
      "type": "string"
    }
  },
  "required": [
    "servicios_recomendados",
    "alcance_propuesto",
    "complejidad",
    "justificacion"
  ]
}
